from pathlib import Path

path = Path('ClockTimer.js')
text = path.read_text()

start = text.index('        #splitRangeForOverwrite(\n')
end = text.index('        #applyOverwriteMask(\n', start)
replacement = '''        #splitRangeForOverwrite(\n            range,\n            leftStart,\n            leftEnd,\n            rightStart,\n            rightEnd\n        ) {\n            if (\n                typeof range.split !==\n                    "function"\n            ) {\n                return;\n            }\n\n            const preserveRangeLength =\n                range.hasAttribute(\n                    "range-length"\n                );\n\n            const splitRanges =\n                range.split(\n                    this.#formatTimelineTime(\n                        leftEnd\n                    ),\n                    true\n                );\n\n            if (\n                !Array.isArray(splitRanges) ||\n                splitRanges.length < 2\n            ) {\n                return;\n            }\n\n            const left =\n                splitRanges[0];\n\n            const right =\n                splitRanges[\n                    splitRanges.length - 1\n                ];\n\n            this.#copyClockTimerRangeState(\n                range,\n                right\n            );\n\n            this.#setRangeTiming(\n                left,\n                leftStart,\n                leftEnd,\n                preserveRangeLength\n            );\n\n            this.#setRangeTiming(\n                right,\n                rightStart,\n                rightEnd,\n                preserveRangeLength\n            );\n\n            const ring =\n                this.#ensureRing(\n                    this.#getRingIndex(\n                        rightStart\n                    )\n                );\n\n            if (\n                right.parentElement !==\n                    ring\n            ) {\n                ring.appendChild(\n                    right\n                );\n            }\n        }\n\n'''
text = text[:start] + replacement + text[end:]

start = text.index('        #replaceRangeWithSegments(\n')
end = text.index('        #shiftExistingTimeRanges(\n', start)
replacement = '''        #replaceRangeWithSegments(\n            range,\n            spans\n        ) {\n            const preserveRangeLength =\n                range.hasAttribute(\n                    "range-length"\n                );\n\n            const segments = [];\n\n            for (\n                const [\n                    spanStart,\n                    spanEnd\n                ] of spans\n            ) {\n                if (\n                    !Number.isFinite(spanStart) ||\n                    !Number.isFinite(spanEnd) ||\n                    spanEnd <= spanStart\n                ) {\n                    continue;\n                }\n\n                let cursor =\n                    spanStart;\n\n                while (\n                    cursor < spanEnd\n                ) {\n                    const ringIndex =\n                        this.#getRingIndex(\n                            cursor\n                        );\n\n                    const ringEnd =\n                        this.#getRingStart(\n                            ringIndex\n                        ) +\n                        ClockTimer.#HOUR;\n\n                    const segmentEnd =\n                        Math.min(\n                            spanEnd,\n                            ringEnd\n                        );\n\n                    segments.push({\n                        start: cursor,\n                        end: segmentEnd,\n                        ringIndex\n                    });\n\n                    cursor =\n                        segmentEnd;\n                }\n            }\n\n            if (segments.length === 0) {\n                range.remove();\n                return;\n            }\n\n            if (segments.length > 1) {\n                if (\n                    typeof range.split !==\n                        "function"\n                ) {\n                    return;\n                }\n\n                const sourceStart =\n                    Number(\n                        range.clockTimerStart\n                    );\n\n                const sourceEnd =\n                    Number(\n                        range.clockTimerEnd\n                    );\n\n                if (\n                    !Number.isFinite(sourceStart) ||\n                    !Number.isFinite(sourceEnd) ||\n                    sourceEnd <= sourceStart\n                ) {\n                    return;\n                }\n\n                const pieces = [\n                    range\n                ];\n\n                let sourceCursor =\n                    sourceStart;\n\n                let currentPiece =\n                    range;\n\n                for (\n                    let index = 0;\n                    index < segments.length - 1;\n                    index++\n                ) {\n                    const duration =\n                        segments[index].end -\n                        segments[index].start;\n\n                    sourceCursor +=\n                        duration;\n\n                    const splitRanges =\n                        currentPiece.split(\n                            this.#formatTimelineTime(\n                                sourceCursor\n                            ),\n                            true\n                        );\n\n                    if (\n                        !Array.isArray(splitRanges) ||\n                        splitRanges.length < 2\n                    ) {\n                        return;\n                    }\n\n                    const right =\n                        splitRanges[\n                            splitRanges.length - 1\n                        ];\n\n                    this.#copyClockTimerRangeState(\n                        range,\n                        right\n                    );\n\n                    pieces.push(\n                        right\n                    );\n\n                    currentPiece =\n                        right;\n                }\n\n                for (\n                    let index = 0;\n                    index < segments.length;\n                    index++\n                ) {\n                    const piece =\n                        pieces[index];\n\n                    const entry =\n                        segments[index];\n\n                    this.#setRangeTiming(\n                        piece,\n                        entry.start,\n                        entry.end,\n                        preserveRangeLength\n                    );\n\n                    const ring =\n                        this.#ensureRing(\n                            entry.ringIndex\n                        );\n\n                    if (\n                        piece.parentElement !==\n                            ring\n                    ) {\n                        ring.appendChild(\n                            piece\n                        );\n                    }\n                }\n\n                return;\n            }\n\n            const entry =\n                segments[0];\n\n            this.#setRangeTiming(\n                range,\n                entry.start,\n                entry.end,\n                preserveRangeLength\n            );\n\n            const ring =\n                this.#ensureRing(\n                    entry.ringIndex\n                );\n\n            if (\n                range.parentElement !== ring\n            ) {\n                ring.appendChild(\n                    range\n                );\n            }\n        }\n\n'''
text = text[:start] + replacement + text[end:]

path.write_text(text)
